mapper.select:
SELECT u.id AS user_id, u.display_name FROM kb_document d CROSS JOIN sys_user u JOIN sys_dept dept ON dept.id = u.dept_id
WHERE d.id = #{documentId} AND d.status <> 'deleted' AND 
AND u.display_name LIKE #{namePattern} ESCAPE '\'
AND u.id > #{afterId}
ORDER BY u.id LIMIT #{limit}

SELECT d.id AS document_id, NULL AS title, f.responsible_user_id, responsible.display_name, f.cycle_months, f.last_confirmed_on, f.due_date, COALESCE(f.stewardship_version, 0) AS stewardship_version, AS eligible, NULL AS version_id, NULL AS effective_from, 'UNDECLARED' AS until_kind, NULL AS effective_until, FALSE AS corrected FROM kb_document d LEFT JOIN kb_document_stewardship f ON f.doc_id = d.id LEFT JOIN sys_user responsible ON responsible.id = f.responsible_user_id WHERE d.space_id = #{spaceId} AND d.status <> 'deleted' AND
f.responsible_user_id IS NULL f.responsible_user_id IS NOT NULL AND NOT f.responsible_user_id IS NOT NULL AND AND f.due_date >= #{today} AND f.due_date <= CAST(#{today} AS DATE) + 30 f.responsible_user_id IS NOT NULL AND AND f.due_date < #{today} FALSE
AND (f.due_date, d.id) > (#{afterDate}, #{afterId}) d.id > #{afterId}
ORDER BY f.due_date, d.id LIMIT #{limit}
